--Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) as revenue
FROM customer
GROUP BY gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 
SELECT customer_id, purchase_amount 
FROM customer 
WHERE discount_applied = 'Yes'
AND purchase_amount >= 
(SELECT AVG(purchase_amount) AS avg_purchase_amount FROM customer);

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased, ROUND(AVG(review_rating::numeric),2) as avg_review_rating
FROM customer
GROUP BY item_purchased
ORDER BY avg_review_rating DESC LIMIT 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
SELECT shipping_type, ROUND(AVG(purchase_amount),2) AS avg_purchase_amount FROM customer
WHERE shipping_type = 'Express' OR shipping_type = 'Standard'
GROUP BY shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
SELECT subscription_status,
COUNT(customer_id) AS total_customers,
SUM(purchase_amount) AS total_revenue,
ROUND(AVG(purchase_amount),2) as average_spend
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, average_spend DESC;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased, 
COUNT(*) AS discounted_purchases,
ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / Count(*),2)
AS pct_purchases_with_discount
FROM customer 
GROUP BY item_purchased
ORDER BY pct_purchases_with_discount DESC LIMIT 5;


SELECT item_purchased, 
COUNT(*) AS discounted_purchases,
ROUND(100.0 * COUNT(*) /
(SELECT COUNT(*) FROM customer c2 WHERE c2.item_purchased = c1.item_purchased),2)
AS pct_purchases_with_discount
FROM customer c1
WHERE discount_applied = 'Yes'
GROUP BY item_purchased
ORDER BY pct_purchases_with_discount DESC LIMIT 5;

--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 

WITH customer_type AS
(SELECT customer_id,
CASE
WHEN previous_purchases = 1 THEN 'New'
WHEN previous_purchases Between 2 AND 10 THEN 'Returning'
ELSE 'Loyal'
END AS customer_segment FROM customer)

SELECT customer_segment, COUNT(*) as "Number of Customers"
FROM customer_type
GROUP BY customer_segment;

--Q8. What are the top 3 most purchased products within each category? 
WITH product_orders AS
(SELECT category, item_purchased, COUNT(*) AS total_orders
FROM customer
GROUP BY category, item_purchased),

ranked_products AS 
(SELECT category, item_purchased, total_orders,
ROW_NUMBER() OVER( 
PARTITION BY category 
ORDER BY total_orders DESC) as product_rank
FROM product_orders)

SELECT product_rank, category, item_purchased, total_orders FROM ranked_products
WHERE product_rank <=3 ORDER BY category, product_rank;
 
--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status, COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. What is the revenue contribution of each age group? 

SELECT age_group, SUM(purchase_amount) AS total_revenue,
ROUND(SUM(purchase_amount)*100.0 / 
(SELECT SUM(purchase_amount) FROM customer),2)
AS "revenue_cotnribution %"
FROM customer 
GROUP BY age_group
ORDER BY total_revenue DESC;